import React, { forwardRef, useImperativeHandle, useRef } from 'react';
import { Box } from '@mui/material';
import BadgeBase from './BadgeBase';

const BinaryBadge = forwardRef(function BinaryBadge(
    { badge, leftIconKey, rightIconKey, ...otherProps },
    ref
) {
    const nodeRef = useRef(null);

    useImperativeHandle(ref, () => ({
        downloadBadge: () => {
            try {
                const { downloadNodeAsPng } = require('../utils/downloadUtils');
                const fileName = `${(badge.label || 'badge').replace(/\s+/g, '_')}.png`;
                downloadNodeAsPng(nodeRef.current, fileName, 20);
            } catch (e) {
                // no-op if consumer doesn't bundle the util
            }
        },
    }));

    return (
        <div ref={nodeRef} style={{ display: 'inline-block' }}>
            <BadgeBase
                label={badge.label}
                description={badge.description}
                avatar={badge.avatar}
                intent={badge.intent}
                type={badge.type}
                leftIconKey={leftIconKey}
                rightIconKey={rightIconKey}
                {...otherProps}
            />
        </div>
    );
});

export default BinaryBadge;


